const input =
  $input.first()?.json ?? {};

const rawLockValue =
  input.lock_acquired;

const lockAcquired =
  rawLockValue === true
  || rawLockValue === 1
  || String(
    rawLockValue ?? ''
  )
    .trim()
    .toLowerCase() === 'true'
  || String(
    rawLockValue ?? ''
  )
    .trim() === '1';

return [
  {
    json: {
      ...input,

      lock_acquired_raw:
        rawLockValue ?? null,

      lock_acquired_boolean:
        lockAcquired,

      lock_acquired_flag:
        lockAcquired ? 1 : 0,

      lock_route:
        lockAcquired
          ? 'LOCK_ACQUIRED'
          : 'LOCK_NOT_ACQUIRED',

      normalized_by:
        'WF-012',

      normalized_at:
        new Date().toISOString(),
    },
  },
];

const items =
  $input.all();

return items.map((item) => {
  const input =
    item.json ?? {};

  const rawHasDocument =
    input.has_document;

  const hasDocument =
    rawHasDocument === true
    || rawHasDocument === 1
    || String(
      rawHasDocument ?? ''
    )
      .trim()
      .toLowerCase() === 'true'
    || String(
      rawHasDocument ?? ''
    )
      .trim() === '1';

  return {
    json: {
      ...input,

      has_document_raw:
        rawHasDocument ?? null,

      has_document_boolean:
        hasDocument,

      document_route:
        hasDocument
          ? 'DOCUMENT_AVAILABLE'
          : 'NO_DOCUMENTS',

      normalized_by:
        'WF-012',

      normalized_at:
        new Date().toISOString(),
    },
  };
});
